#!/usr/bin/env python3
from pathlib import Path
import re
root=Path('source')

def replace_between(text,start_marker,end_marker,replacement):
    a=text.index(start_marker); b=text.index(end_marker,a)
    return text[:a]+replacement+text[b:]

p=root/'app/app.c'; s=p.read_text()
s=s.replace('editor_tx[n++]=42;', 'editor_tx[n++]=1;')
new_helper='/* RC1 V-Station-inspired 240x240 device theme mockup.  This uses only the\n   drawing primitives and fonts available on the FM1, so the simulator output\n   is representative of the real panel rather than desktop concept art. */\n#define VS_BLUE RGB(10,74,166)\n#define VS_BLUE2 RGB(24,112,224)\n#define VS_NAVY RGB(5,13,29)\n#define VS_PANEL RGB(12,24,44)\n#define VS_PANEL2 RGB(18,36,62)\n#define VS_SILVER RGB(178,188,202)\n#define VS_SILVER2 RGB(110,124,143)\n#define VS_TEXT RGB(232,240,252)\nstatic void draw_header_strips(const char *title){\n unsigned sh=strip_h(240);cv_stream_begin(0,0,240,46);\n for(unsigned y=0;y<46;y+=sh){unsigned h=46-y;if(h>sh)h=sh;\n  cv_begin(240,h,VS_NAVY);\n  cv_rect(0,-(int)y,240,23,VS_BLUE);\n  cv_rect(0,23-(int)y,240,23,VS_SILVER);\n  cv_rect(0,22-(int)y,240,2,VS_BLUE2);\n  cv_text(5,3-(int)y,&FONT_XS,"NOVATION",C_WHITE);\n  cv_text(91,1-(int)y,&FONT_B,"V-STATION",C_WHITE);\n  cv_text(7,27-(int)y,&FONT_XS,title,RGB(12,38,88));\n  cv_stream_chunk();\n }\n}\nstatic void draw_full_row(unsigned screen_y,unsigned height,const char *name,const char *text){\n unsigned sh=strip_h(240);cv_stream_begin(0,screen_y,240,height);\n for(unsigned y=0;y<height;y+=sh){unsigned h=height-y;if(h>sh)h=sh;\n  cv_begin(240,h,VS_NAVY);cv_rect(3,-(int)y,234,height-2,VS_PANEL);cv_rect(3,-(int)y,4,height-2,VS_BLUE2);\n  cv_text(10,1-(int)y,&FONT_XS,name,VS_SILVER);cv_text(232-text_w(&FONT_S,text),0-(int)y,&FONT_S,text,VS_TEXT);cv_stream_chunk();\n }\n}\nstatic void draw_footer_strips(const char *text,const char *oct){\n unsigned sh=strip_h(240);cv_stream_begin(0,214,240,26);\n for(unsigned y=0;y<26;y+=sh){unsigned h=26-y;if(h>sh)h=sh;\n  cv_begin(240,h,VS_NAVY);cv_rect(0,-(int)y,240,2,VS_BLUE2);cv_text(5,5-(int)y,&FONT_T,"FM1  RC1",VS_SILVER);cv_text(65,4-(int)y,&FONT_T,text,C_WHITE);cv_text(218,3-(int)y,&FONT_S,oct,C_HI);cv_stream_chunk();\n }\n}\nstatic void draw_param_tile(unsigned x,unsigned y,const char *label,const char *value,const felucca_font_t *vf){\n unsigned sh=strip_h(120);unsigned k=1u+(x?1u:0u)+(y>46?2u:0u);char kt[3]={\'K\',(char)(\'0\'+k),0};cv_stream_begin(x,y,120,84);\n for(unsigned sy=0;sy<84;sy+=sh){unsigned h=84-sy;if(h>sh)h=sh;\n  cv_begin(120,h,VS_NAVY);\n  cv_rect(2,-(int)sy,116,80,VS_PANEL);\n  cv_rect(2,-(int)sy,116,20,VS_SILVER);\n  cv_rect(2,20-(int)sy,116,3,VS_BLUE2);\n  cv_rect(2,23-(int)sy,5,57,VS_BLUE);\n  cv_text(7,2-(int)sy,&FONT_XS,label,RGB(8,34,82));\n  cv_text(97,3-(int)sy,&FONT_T,kt,RGB(8,34,82));\n  cv_text(10,36-(int)sy,vf,value,VS_TEXT);\n  cv_stream_chunk();\n }\n}\nstatic void draw_preset_strips(void){\n static const char *const status[]={"READY","LOADING","LOADED","LOAD FAILED","CANCELLED"};\n const char *name=browser_index?factory_preset_names[browser_index-1]:(editor_custom?"Custom":"Init");\n const char *category=editor_custom?"EDITED / USER PATCH":(browser_index?factory_category_names[factory_preset_categories[browser_index-1]]:"INITIAL PATCH");\n char slot[16];if(browser_index)number((int)browser_index,slot);else slot[0]=0;\n unsigned sh=strip_h(240);cv_stream_begin(0,46,240,96);\n for(unsigned y=0;y<96;y+=sh){unsigned h=96-y;if(h>sh)h=sh;\n  cv_begin(240,h,VS_NAVY);cv_rect(5,6-(int)y,230,66,VS_PANEL);cv_rect(5,6-(int)y,230,3,VS_BLUE2);cv_rect(5,9-(int)y,5,63,VS_BLUE);\n  cv_text(14,15-(int)y,&FONT_B,name,VS_TEXT);cv_text(14,42-(int)y,&FONT_XS,category,VS_SILVER);\n  if(browser_index){cv_text(184,41-(int)y,&FONT_S,slot,C_HI);cv_text(207,42-(int)y,&FONT_T,"/175",C_HI);}\n  cv_rect(5,78-(int)y,230,18,RGB(8,42,88));cv_text(10,79-(int)y,&FONT_XS,status[browser_status],C_WHITE);cv_stream_chunk();\n }\n cv_stream_begin(0,142,240,98);\n for(unsigned y=0;y<98;y+=sh){unsigned h=98-y;if(h>sh)h=sh;\n  cv_begin(240,h,VS_NAVY);cv_rect(5,5-(int)y,230,82,VS_PANEL2);cv_text(10,12-(int)y,&FONT_XS,"SELECT / PRESET: BROWSE",VS_TEXT);\n  cv_text(10,34-(int)y,&FONT_XS,"SEL: LOAD PATCH",C_HI);cv_text(10,56-(int)y,&FONT_XS,"175 FACTORY PATCHES",VS_SILVER);cv_text(10,76-(int)y,&FONT_XS,"HOME: EXIT",VS_SILVER);cv_stream_chunk();\n }\n}\n'
s=replace_between(s,'static void draw_header_strips','static void draw(void)',new_helper)
new_splash='void app_splash(void){\n /* RC1 device splash: vector-only so the V-Station artwork costs almost no flash/RAM. */\n drawn_page=~0u;lcd_fill(0,0,240,240,VS_NAVY);unsigned sh=strip_h(240);cv_stream_begin(0,0,240,240);\n for(unsigned y=0;y<240;y+=sh){unsigned h=240-y;if(h>sh)h=sh;cv_begin(240,h,VS_NAVY);\n  /* blue/silver V-Station frame */\n  cv_rect(0,-(int)y,240,40,VS_BLUE);cv_rect(0,38-(int)y,240,3,VS_BLUE2);\n  cv_rect(0,40-(int)y,240,9,VS_SILVER);cv_rect(0,190-(int)y,240,7,VS_SILVER);\n  cv_rect(0,197-(int)y,240,43,VS_BLUE);cv_rect(0,196-(int)y,240,3,VS_BLUE2);\n  cv_text(45,8-(int)y,&FONT_L,"NOVATION",C_WHITE);\n  /* compact synth-panel illustration, feasible on the actual 240x240 LCD */\n  cv_rect(18,61-(int)y,204,112,VS_SILVER);cv_rect(22,65-(int)y,196,104,VS_PANEL);\n  cv_rect(22,65-(int)y,196,17,VS_BLUE);cv_text(31,66-(int)y,&FONT_T,"FM1",C_WHITE);cv_text(91,65-(int)y,&FONT_B,"V-STATION",C_WHITE);\n  cv_rect(28,88-(int)y,55,73,VS_PANEL2);cv_rect(88,88-(int)y,55,73,VS_PANEL2);cv_rect(148,88-(int)y,64,73,VS_PANEL2);\n  cv_text(33,91-(int)y,&FONT_T,"OSC",VS_SILVER);cv_text(94,91-(int)y,&FONT_T,"FILTER",VS_SILVER);cv_text(154,91-(int)y,&FONT_T,"FX / ENV",VS_SILVER);\n  for(unsigned k=0;k<3;k++){int yy=111+(int)k*15;cv_rect(34,yy-(int)y,9,9,VS_BLUE2);cv_rect(51,yy-(int)y,22,5,VS_SILVER2);cv_rect(96,yy-(int)y,9,9,VS_BLUE2);cv_rect(113,yy-(int)y,22,5,VS_SILVER2);cv_rect(156,yy-(int)y,9,9,VS_BLUE2);cv_rect(173,yy-(int)y,29,5,VS_SILVER2);}\n  cv_text(31,204-(int)y,&FONT_L,"V-STATION",C_WHITE);cv_text(73,229-(int)y,&FONT_T,"RC1  LOADING",VS_TEXT);\n  cv_stream_chunk();\n }\n}\n'
s=re.sub(r'void app_splash\(void\)\{.*?\}(?=\nvoid app_ui_init)',new_splash.rstrip(),s,flags=re.S)
p.write_text(s)

p=root/'app/app.h'; s=p.read_text(); s=re.sub(r'#define APP_TAGLINE ".*?"','#define APP_TAGLINE "RC1"',s); p.write_text(s)
p=root/'app/fm1.toml'; s=p.read_text();
s=re.sub(r'usb_manufacturer = ".*?"','usb_manufacturer = "FM1 V-Station"',s)
s=re.sub(r'usb_product = ".*?"','usb_product = "VStation RC1"',s)
s=re.sub(r'tagline = ".*?"','tagline = "8-voice shared-pool V-Station port"',s)
p.write_text(s)

(root/'build.sh').write_text('#!/usr/bin/env bash\nset -euo pipefail\ncd "$(dirname "$0")"\nexport AC79_SDK="${AC79_SDK:-$PWD/build-deps/sdk}"\nexport X0X_FONTSET=barlow\nt="$PWD/build-toolchain/jieli-linux-toolchains-20260730.1"\nif [[ -n "${JIELI_TOOLCHAIN:-}" && -x "${JIELI_TOOLCHAIN}/pi32v2/bin/clang" ]]; then\n :\nelif [[ -x "$t/pi32v2/bin/clang" ]]; then\n export JIELI_TOOLCHAIN="$t"\nelif [[ -f toolchain/jieli-linux-toolchains-20260730.1.tar.xz ]]; then\n mkdir -p build-toolchain\n tar --no-same-owner -xJf toolchain/jieli-linux-toolchains-20260730.1.tar.xz -C build-toolchain\n export JIELI_TOOLCHAIN="$t"\nelse\n echo "Missing JieLi toolchain. Set JIELI_TOOLCHAIN to jieli-linux-toolchains-20260730.1 or place its .tar.xz under toolchain/." >&2\n exit 2\nfi\npython3 base/tools/build.py app --release 1.0.0 --display-version "RC1" "$@"\nif [[ " $* " == *" --host "* || " $* " == *" --web "* ]]; then exit 0; fi\nmkdir -p release\ncp app/build/vstation-1.0.0.fwsc release/FM1-VStation-RC1.fwsc\nif [[ -f reference/FM1-PolyWavetable-TEST81-M-Flasher.bin ]]; then\n python3 tools/make_mflasher.py reference/FM1-PolyWavetable-TEST81-M-Flasher.bin release/FM1-VStation-RC1-M-Flasher.bin --app app/build/vstation.bin\nelse\n echo "Reference full image not present; built FWSC only. The prebuilt RC1 M-Flasher image is under release/." >&2\nfi\n'); (root/'build.sh').chmod(0o755)
for fn in ['web-editor/index.html','web-editor/generate_editor.py']:
    p=root/fn; s=p.read_text();
    s=s.replace('Connect TEST42 8V to start telemetry.','Connect RC1 to start telemetry.')
    s=s.replace('MIDI opened; TEST42 8V did not answer SysEx','MIDI opened; RC1 did not answer SysEx')
    p.write_text(s)
p=root/'tests/editor_protocol_test.py'
if p.exists():
    s=p.read_text().replace("'firmware':'TEST42 8V'","'firmware':'RC1'"); p.write_text(s)
(root/'README.md').write_text('# FM1 V-Station RC1\n\nAn FM1 port/reconstruction inspired by the Novation V-Station architecture. RC1 combines the tested **8-voice shared dynamic pool** with the approved device-native V-Station-style 240x240 GUI and startup splash.\n\n## RC1 highlights\n\n- **8 physical voices in one shared dynamic pool** — POOL 1..8, default 8\n- global allocation and whole-unison-group voice stealing\n- unison 1x..4x\n- dual-core 4+4 rendering at a full eight-voice load\n- 175 retained factory presets / 13 categories\n- 170 active synth parameters\n- device-native **240x240 RGB565 V-Station-inspired GUI**\n- blue/silver header, dark parameter panels and explicit K1..K4 mappings\n- V-Station-themed vector loading splash with NOVATION / V-STATION branding\n- USB-C Web MIDI editor with JSON preset import/export and persistent browser user library\n- live FM1 CPU/deadline/underrun telemetry\n- browsable source tree, build scripts and prebuilt firmware included\n\nAt unison 1x, POOL 8 provides eight simultaneous physical voices; at 2x it provides four notes; at 4x it provides two notes. The voices are not statically reserved per part.\n\n## Firmware\n\nPreferred update:\n\n`release/FM1-VStation-RC1.fwsc`\n\nComplete image:\n\n`release/FM1-VStation-RC1-M-Flasher.bin`\n\nKeep your own full-device backup before using a complete M-Flasher image because non-application regions come from the pinned project reference image.\n\n## Source\n\nThe source is available two ways:\n\n- `source/` — browsable directly on GitHub\n- `release/FM1-VStation-RC1-Source.zip` — the matching downloadable source package\n\nThe source tree includes the application, engine, fm1-base platform snapshot, tests, web editor generator, build scripts and generated font/word headers. Large external build inputs are intentionally excluded; see `DEPENDENCIES.md`.\n\n## Building\n\nSet `JIELI_TOOLCHAIN` to the validated JieLi toolchain, or place `jieli-linux-toolchains-20260730.1.tar.xz` under `toolchain/`.\n\n```bash\nbash build.sh\n```\n\nHost simulator:\n\n```bash\nbash build.sh --host\n```\n\nThe full M-Flasher image additionally requires the pinned reference image listed in `DEPENDENCIES.md`. Without it, the normal `.fwsc` still builds.\n\n## Web editor\n\nUse `web-editor/index.html` from `source/` or the packaged `release/FM1-VStation-RC1-Web-Editor.zip`. Connect the FM1 over USB-C in a Web MIDI/SysEx-capable Chromium browser.\n\nThe hardware page exposes POOL 1..8, DUAL/SINGLE CPU mode, scan diagnostics and live performance telemetry.\n\n## RC1 target footprint\n\n- Application: **566,400 / 581,564 bytes**\n- Main RAM: **94,928 / 98,304 bytes**\n- FX/large-buffer pool: **335,692 / 344,064 bytes**\n- Firmware identity: **`FM-1_15010000`**\n\nSee `RC1-RELEASE-NOTES.md` for validation details.\n\n## Licensing / provenance\n\nThe FM1 platform layer is based on `fm1-base` / Felucca BSP and retains its applicable open-source licensing. No Novation proprietary source code is included. This is an independent reconstruction/port from supplied executable/data behavior and public operating information.\n')
(root/'RC1-RELEASE-NOTES.md').write_text('# FM1 V-Station RC1\n\nRC1 is the tested eight-voice shared-pool V-Station port with the approved on-device V-Station-inspired GUI and startup splash.\n\n## Engine\n\n- Eight physical native voices in one dynamically shared global pool.\n- Runtime POOL selector 1..8, default 8.\n- No fixed per-part reservation: any free physical voice can service the next note/unison group.\n- Unison remains 1x..4x; two independent 4x-unison notes can consume all eight physical voices.\n- Whole-group voice stealing and the existing steal crossfade are retained.\n- Dual-core rendering naturally divides a full eight-voice load 4+4.\n- 175 retained factory presets across 13 categories.\n- 170 active synth parameters and USB-C Web MIDI editor retained.\n\n## On-device GUI\n\n- Native FM1 display size: 240x240 RGB565.\n- V-Station-inspired blue/silver header and dark-blue parameter panels.\n- Four-parameter pages retain direct K1..K4 mapping.\n- K1..K4 labels are rendered on the parameter tiles.\n- Preset browser uses the same device-native visual theme.\n- Performance/CPU diagnostic pages retain live counters.\n- New vector startup splash: NOVATION at the top, stylized V-Station panel in the center, V-STATION / RC1 at the bottom.\n- The splash is drawn from FM1 primitives rather than storing a full 240x240 bitmap, preserving flash headroom.\n\n## Target build\n\n- Firmware identity: `FM-1_15010000`\n- Display version: `RC1`\n- Application: 566,400 / 581,564 bytes\n- Main RAM: 94,928 / 98,304 bytes\n- FX/large-buffer pool: 335,692 / 344,064 bytes\n- FWSC: 610,108 bytes\n\nThe target audit passes: no software-double helpers, no app-side raw register access, valid M-Flasher directory CRCs, and exact decrypted application verification.\n\n## Validation status\n\nThe eight-voice baseline previously passed allocator, whole-unison-group stealing, dual-core worker, sanitizer, and all-175-factory-preset render regressions. The user reported the first physical eight-voice test **seems good**.\n\nFor this GUI build, source-consistency, POOL 1..8 UI, preset-browser and USB editor protocol regressions pass, as does the FM1 target link/audit. The long all-sanitizer suite was not fully re-run after the cosmetic-only GUI change; DSP source is unchanged from the tested eight-voice baseline.\n')
